/* Confetti — the files UnrealIRCd ships, and making your own version.
 *
 * Every `*.default.conf` says the same thing in its own header, in capitals:
 * DO NOT EDIT THIS FILE! IT WILL BE OVERWRITTEN DURING NEXT UPGRADE!! Work you
 * do in one of them disappears the next time the server is updated, and there
 * is nothing at the time to tell you that is going to happen.
 *
 * So they are read-only here, and refusing is only half of it — the other half
 * is doing the thing you were actually trying to do. Each shipped file already
 * documents how it wants to be customised, and they do not all agree, so the
 * facility follows each file's own advice rather than one invented rule.
 */

const isShipped = (f) => !!f && /\.default\.conf$/i.test(f.name);
const ownNameFor = (f) => f.name.replace(/\.default\.conf$/i, ".custom.conf");

/* Beside or instead: the module lists and operclasses are layered on top,
   because a later block wins and blacklist-module and parent exist for that.
   snomasks is copied and swapped in, because its log blocks are additive and a
   second set alongside the first routes every snomask twice. Kept in step with
   own_kind() in lib.rs. */
const REPLACES = new Set(["snomasks.default.conf"]);

function ownStory(f) {
  const own = ownNameFor(f);
  if (REPLACES.has(f.name.toLowerCase())) {
    return {
      title: `Make your own ${own}`,
      body: `${own} starts as a copy of this file, and your unrealircd.conf `
          + `includes it instead of this one.`,
      note: "Its log blocks add up rather than override, so a copy is what "
          + "UnrealIRCd's own header tells you to make.",
    };
  }
  return {
    title: `Make your own ${own}`,
    body: `${own} is created beside this file and included straight after it, `
        + `so anything you put there wins.`,
    note: `${f.name} keeps being included, so you only write down what you `
        + "want different.",
  };
}

async function makeOwn(f) {
  const s = ownStory(f);
  const ok = await confirmAsk({
    title: s.title,
    body: s.body,
    note: s.note,
    okLabel: "Create it",
  });
  if (!ok) return;
  try {
    const ws = await invoke("make_own", { file: f.path });
    if (ws) {
      await loadWorkspace(ws);
      const own = ownNameFor(f);
      const made = state.ws.files.find((x) => x.name === own);
      if (made) { state.file = made.rel; state.sel = null; }
      render();
      await refreshProblems();
    }
  } catch (e) { oops(e); }
}

/* ---------------- saying so ---------------- */

/* In the tree: a mark, and the row reads as not-yours. */
const shipBaseRenderTree = renderTree;
renderTree = function () {
  shipBaseRenderTree();
  if (!state.ws) return;
  for (const row of document.querySelectorAll("#tree .trow")) {
    const f = row.__file;
    if (!isShipped(f)) continue;
    row.classList.add("shipped");
    const nm = row.querySelector(".nm");
    if (nm) nm.title = `${f.name} is installed by UnrealIRCd and replaced on upgrade`;
    const mark = el("span", "shipmark", "▪");
    mark.title = "Read-only — UnrealIRCd replaces this file when you upgrade";
    row.insertBefore(mark, row.querySelector(".n") || null);
  }
};

/* In the inspector: the offer, where you are when you notice you want it. */
const shipBaseRenderInspector = renderInspector;
renderInspector = function () {
  shipBaseRenderInspector();
  if (!state.ws) return;
  const f = state.sel ? fileByPath(state.sel.file) : (state.file ? fileOf(state.file) : null);
  if (!isShipped(f)) return;

  const p = $("insp");
  const box = el("div", "shipnote");
  box.appendChild(el("div", "shiphead", `${f.name} is UnrealIRCd's`));
  box.appendChild(el("div", "tiny",
    "It is replaced when you upgrade the server, so Confetti will not write to "
    + "it. Anything you changed here would be gone after the next update."));
  const b = el("button", "btn go wide", `Make your own ${ownNameFor(f)}`);
  b.addEventListener("click", () => makeOwn(f));
  box.appendChild(b);
  // Put it at the top: it is the answer to the question you are about to ask.
  p.insertBefore(box, p.firstChild);
};

/* In the file menu, next to everything else you might do to a file. */
const shipBaseFileMenu = fileMenu;
fileMenu = function (ev, f) {
  shipBaseFileMenu(ev, f);
  const m = document.querySelector(".menu:not(.sub)");
  if (!m || !isShipped(f)) return;
  menuAppend(m, [
    "-",
    { heading: "this one is UnrealIRCd's" },
    { label: `Make your own ${ownNameFor(f)}…`,
      hint: "Yours is included after it, and survives upgrades",
      run: () => makeOwn(f) },
  ]);
};

/* Editing controls on a shipped file are removed rather than left to fail.
   The backend refuses every write regardless — this is so you are not invited
   to try. */
const shipBaseRender = render;
render = function () {
  shipBaseRender();
  const f = state.file ? fileOf(state.file) : null;
  document.body.classList.toggle("on-shipped", isShipped(f));
};
